// Function node "ingest config". In: retained zigdash/history/config.
// Keeps the config and an index from device state topic to the readings
// recorded from it. An empty payload stops recording; records already on
// the broker stay until they age out.
const raw = msg.payload;
const empty = raw === undefined || raw === null ||
    (typeof raw === 'string' && raw.trim() === '') ||
    (Buffer.isBuffer(raw) && raw.length === 0);
if (empty) {
    flow.set('cfg', null);
    flow.set('index', {});
    return null;
}
const cfg = (typeof raw === 'object' && !Buffer.isBuffer(raw)) ? raw : JSON.parse(raw.toString());
const index = {};
const keys = new Set();
for (const r of (cfg.readings || []).slice(0, 50)) {
    if (!r.topic || !r.ieee || !r.attr || !r.path) continue;
    const key = r.ieee + '/' + r.attr;
    keys.add(key);
    (index[r.topic] = index[r.topic] || []).push({ key, path: r.path, unit: r.unit || '' });
}
flow.set('cfg', cfg);
flow.set('index', index);
// Forget readings that are no longer recorded.
const mem = flow.get('mem') || {};
for (const k of Object.keys(mem)) if (!keys.has(k)) delete mem[k];
flow.set('mem', mem);
return null;

// Function node "restore today". In: retained zigdash/history/+/+/+ (day
// records, read back on connect and echoed after each publish).
// Node-RED's context on the hub is memory-only, so after a restart today's
// record is the only copy of today's slots. Slots already in memory win:
// the record holds averages, memory holds the exact sums.
const parts = msg.topic.split('/'); // zigdash history <ieee> <attr> <date>
if (parts.length !== 5) return null;
const key = parts[2] + '/' + parts[3];
const date = parts[4];
const cfg = flow.get('cfg');
const tz = (cfg && cfg.timeZone) || 'UTC';
const now = new Date();
const today = new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' }).format(now);
if (date !== today) return null;
const raw = msg.payload;
if (raw === undefined || raw === null || raw === '' || (Buffer.isBuffer(raw) && raw.length === 0)) return null;
let rec;
try { rec = (typeof raw === 'object' && !Buffer.isBuffer(raw)) ? raw : JSON.parse(raw.toString()); } catch (e) { return null; }
const mem = flow.get('mem') || {};
const m = mem[key] && mem[key].date === date ? mem[key] : { date, slots: {}, pub: -1, unit: rec.unit || '' };
for (const b of rec.b || []) {
    const [slot, avg, min, max] = b;
    if (m.slots[slot]) continue;
    m.slots[slot] = [1, avg, min, max];
}
mem[key] = m;
flow.set('mem', mem);
return null;

// Function node "record". In: <base>/# device state messages.
// Folds each configured reading's value into its 15-minute slot of today
// (count, sum, min, max). Publishing happens in "tick".
const index = flow.get('index') || {};
const readings = index[msg.topic];
if (!readings) return null;
let state = msg.payload;
if (Buffer.isBuffer(state)) state = state.toString();
if (typeof state === 'string') { try { state = JSON.parse(state); } catch (e) { return null; } }
if (!state || typeof state !== 'object') return null;
const cfg = flow.get('cfg') || {};
const tz = cfg.timeZone || 'UTC';
const now = new Date();
const p = Object.fromEntries(new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' })
    .formatToParts(now).map(x => [x.type, x.value]));
const date = `${p.year}-${p.month}-${p.day}`;
const slot = Math.floor((Number(p.hour) * 60 + Number(p.minute)) / 15);
const mem = flow.get('mem') || {};
for (const r of readings) {
    let v = state;
    for (const seg of r.path.split('.')) v = v === null || v === undefined ? undefined : v[seg];
    if (typeof v === 'string' && v.trim() !== '') v = Number(v);
    if (typeof v !== 'number' || !isFinite(v)) continue;
    let m = mem[r.key];
    if (!m || m.date !== date) {
        // A new day before "tick" closed the old one: tick publishes the
        // old day from "done" so the last slots are not lost.
        if (m && m.date !== date) {
            const done = flow.get('done') || [];
            done.push({ key: r.key, rec: m });
            flow.set('done', done);
        }
        m = { date, slots: {}, pub: -1, unit: r.unit };
        mem[r.key] = m;
    }
    m.unit = r.unit;
    const s = m.slots[slot];
    m.slots[slot] = s ? [s[0] + 1, s[1] + v, Math.min(s[2], v), Math.max(s[3], v)] : [1, v, v, v];
}
flow.set('mem', mem);
return null;

// Function node "tick", every minute. Publishes each reading's day record
// when a 15-minute slot closes, publishes yesterday's final record after
// midnight, and on a new day clears records older than keepDays.
const cfg = flow.get('cfg');
if (!cfg) return null;
const tz = cfg.timeZone || 'UTC';
const keep = cfg.keepDays || 30;
const fmt = d => {
    const p = Object.fromEntries(new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' })
        .formatToParts(d).map(x => [x.type, x.value]));
    return { date: `${p.year}-${p.month}-${p.day}`, slot: Math.floor((Number(p.hour) * 60 + Number(p.minute)) / 15) };
};
const now = new Date();
const { date, slot } = fmt(now);
const round = x => Math.round(x * 100) / 100;
const record = (key, m, upTo) => {
    const b = Object.keys(m.slots).map(Number).filter(s => s < upTo).sort((a, c) => a - c)
        .map(s => { const [n, sum, min, max] = m.slots[s]; return [s, round(sum / n), round(min), round(max)]; });
    return { topic: `zigdash/history/${key}/${m.date}`, retain: true, payload: JSON.stringify({ v: 1, unit: m.unit || '', b }) };
};
const out = [];
const mem = flow.get('mem') || {};
// Days that "record" closed early.
for (const d of flow.get('done') || []) out.push(record(d.key, d.rec, 96));
flow.set('done', []);
for (const key of Object.keys(mem)) {
    const m = mem[key];
    if (m.date !== date) { // the day ended with no new value since
        out.push(record(key, m, 96));
        mem[key] = { date, slots: {}, pub: -1, unit: m.unit };
        continue;
    }
    if (m.pub !== slot && Object.keys(m.slots).some(s => Number(s) < slot)) {
        out.push(record(key, m, slot));
        m.pub = slot;
    }
}
flow.set('mem', mem);
// A new day (or the first tick after a start): clear old records. A week
// of dates beyond the window, so a recorder that was off for days still
// cleans up.
if (flow.get('day') !== date) {
    flow.set('day', date);
    const index = flow.get('index') || {};
    const keys = new Set();
    for (const rs of Object.values(index)) for (const r of rs) keys.add(r.key);
    for (let back = keep; back < keep + 7; back++) {
        const old = fmt(new Date(now.getTime() - back * 86400000)).date;
        for (const key of keys) out.push({ topic: `zigdash/history/${key}/${old}`, retain: true, payload: '' });
    }
}
return out.length ? [out] : null;
